struct SleepPlan {
  uint64_t seconds;
  std::string reason;  // for the "[sched] ..." log line
};

// Quiet hours applied to an already-decided sleep length, in the two cases that
// matter: we are inside the window right now, or the sleep would land inside
// it. Both end at quiet-end. Factored out of computeSleepPlan() so the failure
// paths get this arithmetic rather than a second copy of it — an error backoff
// that ignores quiet hours is how a broken source turns into 288 wakes a day
// (see deepSleepError). `what` comes back as the tail of a log line so either
// caller can prefix its own reason.
enum class QuietFit { NotApplicable, InsideNow, WouldLandInside };

QuietFit applyQuietHours(const std::string& quietStart, const std::string& quietEnd,
                         time_t nowSched, uint64_t proposedSecs, uint64_t& outSecs,
                         std::string& what);
SleepPlan computeSleepPlan(JsonVariantConst schedule, const DeviceConfig& cfg, time_t nowSched,
                           bool haveTime);
void maybeAdvanceLoopPage(const DeviceConfig& cfg, time_t nowSched, bool haveTime);

[[noreturn]] void lowLevelSleep(uint64_t sleepUs, const char* why);
[[noreturn]] void deepSleepMinutes(uint32_t minutes, const char* why);
[[noreturn]] void deepSleepScheduled(uint64_t sleepSeconds, const char* why);
